package io.ericchernuka.pintprogress.core; import org.junit.Assert.assertEquals; import org.junit.Test; class PintFieldSizeTest { @Test fun `reported physical size takes precedence and converts to dp`() { val densityOne = PintFieldSize.resolve(viewSize = 480 to 200, gridSize = 30 to 15, screenSize = 480 to 800, density = 1f, );         val densityTwo = PintFieldSize.resolve(viewSize = 961 to 401, gridSize = 30 to 15, screenSize = 480 to 800, density = 2f, );         assertEquals(480, densityOne.widthDp);         assertEquals(200, densityOne.heightDp);         assertEquals(481, densityTwo.widthDp);         assertEquals(201, densityTwo.heightDp) };     @Test fun `grid proportions provide each missing physical dimension before conversion`() { val widthFallback = PintFieldSize.resolve(viewSize = 0 to 400, gridSize = 30 to 15, screenSize = 480 to 800, density = 2f, );         val heightFallback = PintFieldSize.resolve(viewSize = 400 to 0, gridSize = 30 to 15, screenSize = 480 to 800, density = 2f, );         assertEquals(120, widthFallback.widthDp);         assertEquals(200, widthFallback.heightDp);         assertEquals(200, heightFallback.widthDp);         assertEquals(100, heightFallback.heightDp) };     @Test fun `invalid density falls back to density one`() { val expected = PintFieldSize.resolve(viewSize = 480 to 200, gridSize = 30 to 15, screenSize = 480 to 800, density = 1f, );         listOf(0f, -2f, Float.NaN, Float.POSITIVE_INFINITY).forEach { invalidDensity -> val actual = PintFieldSize.resolve(viewSize = 480 to 200, gridSize = 30 to 15, screenSize = 480 to 800, density = invalidDensity, );             assertEquals(expected.widthDp, actual.widthDp);             assertEquals(expected.heightDp, actual.heightDp) } } };